SELECT COUNT(*)
FROM selection_batch
WHERE batch_code = #{batchCode}

SELECT EXISTS(
           SELECT 1 FROM questionnaire_version WHERE id = #{questionnaireId}
       ) AS questionnaire_exists,
       EXISTS(
           SELECT 1 FROM matching_weight_scheme WHERE id = #{schemeId}
       ) AS scheme_exists,
       EXISTS(
           SELECT 1 FROM batch_rule_template WHERE id = #{ruleTemplateId}
       ) AS rule_template_exists
